import math
from functools import reduce

def gcd(a, b):
    while b:
        a, b = b, a % b
    return a

def max_gcd_after_move(N, A):
    total_gcd = reduce(gcd, A)

    if total_gcd > 1:
        return total_gcd

    max_gcd = 1
    for i in range(N):
        remaining_gcd = reduce(gcd, A[:i] + A[i+1:])
        for j in range(2, int(math.sqrt(A[i])) + 1):
            if A[i] % j == 0:
                candidate_gcd = gcd(remaining_gcd, j)
                if candidate_gcd > max_gcd:
                    max_gcd = candidate_gcd
                candidate_gcd = gcd(remaining_gcd, A[i] // j)
                if candidate_gcd > max_gcd:
                    max_gcd = candidate_gcd

    return max_gcd

if __name__ == "__main__":
    import sys
    input = sys.stdin.read
    data = input().split()
    N = int(data[0])
    A = list(map(int, data[1:]))
    result = max_gcd_after_move(N, A)
    print(result)
